CREATE TYPE "state_enum" AS ENUM (
  'shock',
  'fear',
  'calm',
  'nostalgia'
);

CREATE TABLE "People" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar,
  "city_id" int
);

CREATE TABLE "PeopleState" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "person_id" int NOT NULL,
  "changed_at" timestamp,
  "intensity" int,
  "state_type" state_enum NOT NULL
);

CREATE TABLE "City" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar,
  "region" varchar
);

CREATE TABLE "MetroLine" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "name" varchar,
  "color" varchar
);

CREATE TABLE "Station" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "line_id" int,
  "name" varchar,
  "city_id" int
);

ALTER TABLE "PeopleState" ADD FOREIGN KEY ("person_id") REFERENCES "People" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "People" ADD FOREIGN KEY ("city_id") REFERENCES "City" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Station" ADD FOREIGN KEY ("line_id") REFERENCES "MetroLine" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Station" ADD FOREIGN KEY ("city_id") REFERENCES "City" ("id") DEFERRABLE INITIALLY IMMEDIATE;
